"use client";

import {
  Menu,
  MenuButton,
  MenuItem,
  MenuItems,
  Tab,
  TabGroup,
  TabList,
  TabPanel,
  TabPanels,
} from "@headlessui/react";
import Link from "next/link";
import { useMemo, useState } from "react";
import { cn } from "@/lib/utils";
import { projectCategories, projects } from "@/data/projects";

const sortOptions = [
  { label: "Newest", value: "newest" },
  { label: "Oldest", value: "oldest" },
  { label: "A-Z", value: "az" },
] as const;

type SortValue = (typeof sortOptions)[number]["value"];

function sortProjects(items: typeof projects, sort: SortValue) {
  const sorted = [...items];

  if (sort === "newest") {
    return sorted.sort((a, b) => Number(b.year) - Number(a.year));
  }

  if (sort === "oldest") {
    return sorted.sort((a, b) => Number(a.year) - Number(b.year));
  }

  return sorted.sort((a, b) => a.title.localeCompare(b.title));
}

export function ProjectTabs() {
  const [sort, setSort] = useState<SortValue>("newest");
  const sortedProjectsByCategory = useMemo(
    () =>
      projectCategories.map((category) => {
        const items =
          category === "All"
            ? projects
            : projects.filter((project) => project.category === category);
        return { category, items: sortProjects(items, sort) };
      }),
    [sort]
  );

  return (
    <TabGroup>
      <div className="flex flex-wrap items-center justify-between gap-4 border-b border-slate-200 pb-4">
        <TabList aria-label="Project categories" className="flex flex-wrap gap-2">
          {projectCategories.map((category) => (
            <Tab
              key={category}
              className={({ selected }) =>
                cn(
                  "rounded-full px-4 py-2 text-sm font-medium transition",
                  selected
                    ? "bg-slate-900 text-white"
                    : "border border-slate-200 text-slate-600 hover:text-slate-900"
                )
              }
            >
              {category}
            </Tab>
          ))}
        </TabList>

        <Menu className="relative">
          <MenuButton className="inline-flex items-center gap-2 rounded-full border border-slate-200 px-4 py-2 text-sm font-medium text-slate-700">
            Sort: {sortOptions.find((option) => option.value === sort)?.label}
            <svg
              aria-hidden="true"
              viewBox="0 0 24 24"
              className="h-4 w-4"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
            >
              <path d="M6 9l6 6 6-6" />
            </svg>
          </MenuButton>
          <MenuItems className="absolute right-0 mt-2 w-40 rounded-xl border border-slate-200 bg-white p-2 text-sm shadow-lg focus:outline-none">
            {sortOptions.map((option) => (
              <MenuItem key={option.value}>
                {({ focus }) => (
                  <button
                    type="button"
                    onClick={() => setSort(option.value)}
                    className={cn(
                      "flex w-full items-center justify-between rounded-lg px-3 py-2 text-left text-slate-700",
                      focus && "bg-slate-100 text-slate-900"
                    )}
                  >
                    {option.label}
                    {sort === option.value ? (
                      <span className="text-xs font-semibold text-slate-500">
                        Active
                      </span>
                    ) : null}
                  </button>
                )}
              </MenuItem>
            ))}
          </MenuItems>
        </Menu>
      </div>

      <TabPanels className="mt-6">
        {sortedProjectsByCategory.map(({ category, items }) => (
          <TabPanel key={category} className="focus:outline-none">
            <div className="grid gap-4 sm:grid-cols-2">
              {items.map((project) => (
                <article
                  key={project.id}
                  className="flex flex-col gap-3 rounded-2xl border border-slate-200 bg-white p-5"
                >
                  <div className="flex items-start justify-between gap-4">
                    <div>
                      <p className="text-xs font-semibold uppercase tracking-wide text-slate-500">
                        {project.category} · {project.year}
                      </p>
                      <h3 className="text-lg font-semibold text-slate-900">
                        {project.title}
                      </h3>
                    </div>
                    {project.href ? (
                      <Link
                        href={project.href}
                        className="text-xs font-semibold text-slate-700 underline-offset-4 hover:underline"
                      >
                        View
                      </Link>
                    ) : null}
                  </div>
                  <p className="text-sm text-slate-600">
                    {project.description}
                  </p>
                  <div className="flex flex-wrap gap-2">
                    {project.tags.map((tag) => (
                      <span
                        key={tag}
                        className="rounded-full bg-slate-100 px-3 py-1 text-xs font-medium text-slate-600"
                      >
                        {tag}
                      </span>
                    ))}
                  </div>
                </article>
              ))}
            </div>
          </TabPanel>
        ))}
      </TabPanels>
    </TabGroup>
  );
}
